export function mountControls(root,bundle,actions){
 const controls=new Map(),cleanup=[];root.replaceChildren();let disposed=false;
 const run=(name,...args)=>{if(disposed)return;try{Promise.resolve(actions[name]?.(...args)).catch(()=>{});}catch{}};
 const listen=(e,name,fn)=>{e.addEventListener(name,fn);cleanup.push(()=>e.removeEventListener(name,fn));};
 for(const d of bundle.catalog.controls){const card=root.ownerDocument.createElement('div'),label=root.ownerDocument.createElement('label'),input=root.ownerDocument.createElement(d.kind===3?'button':'input'),value=root.ownerDocument.createElement('output');card.className='remote-control';label.textContent=d.label;input.id='control-'+d.id;label.htmlFor=input.id;input.setAttribute('aria-label',d.label);input.disabled=true;value.setAttribute('aria-live','polite');card.append(label,input,value);if(d.role){card.dataset.role=d.role.type;card.dataset.index=String(d.role.index);}root.append(card);const item={input,value,last:null,descriptor:d};controls.set(d.id,item);
  if(d.kind===3){input.type='button';input.textContent=d.label;const velocity=Math.min(d.max,Math.max(d.min,100));listen(input,'pointerdown',e=>{if(input.disabled||e.button!==0)return;e.preventDefault();input.setPointerCapture?.(e.pointerId);run('down','pointer:'+d.id+':'+e.pointerId,d.id,velocity);});for(const name of ['pointerup','pointercancel','lostpointercapture'])listen(input,name,e=>run('up','pointer:'+d.id+':'+e.pointerId));listen(input,'keydown',e=>{if(input.disabled||e.repeat||!['Enter',' '].includes(e.key))return;e.preventDefault();run('down','key:'+d.id+':'+e.key,d.id,velocity);});listen(input,'keyup',e=>{if(!['Enter',' '].includes(e.key))return;e.preventDefault();run('up','key:'+d.id+':'+e.key);});listen(input,'blur',()=>{run('up','key:'+d.id+':Enter');run('up','key:'+d.id+': ');});
  }else{input.type='number';input.min=String(d.min);input.max=String(d.max);input.step=d.kind===1?'1':'any';listen(input,'change',()=>{const desired=Number(input.value);input.value=item.last===null?'':String(item.last);if(!input.disabled&&Number.isFinite(desired))run('set',d.id,desired);});}
 }
 return{controls,update(state){if(disposed)return;for(const [id,item]of controls){const v=state.values?.find(v=>v.id===id),unavailable=!v||v.available===false;item.input.disabled=state.phase!=='ready'||unavailable;item.input.setAttribute('aria-disabled',String(item.input.disabled));if(unavailable){item.last=null;item.input.value='';item.value.textContent='Not active';if(item.descriptor.kind===3)item.input.setAttribute('aria-pressed','false');continue;}if(v){item.last=v.value;if(item.descriptor.kind!==3)item.input.value=String(v.value);item.value.textContent=v.queued?'Queued; refresh to confirm':String(v.value);}if(item.descriptor.kind===3){const held=(state.held??[]).includes(id);item.input.setAttribute('aria-pressed',String(held));item.value.textContent=held?'Held · confirmed':'';}}},destroy(){if(disposed)return;disposed=true;for(const f of cleanup)f();for(const item of controls.values())item.input.disabled=true;}};
}
